const fs = require('fs');

class WordReader {
    constructor(input) {
        this.tokens = input.trim().split(/\s+/);
        this.index = 0;
    }
    sl() {
        return this.tokens[this.index++];
    }
    s() {
        return this.sl();
    }
    i() {
        return parseInt(this.sl(), 10);
    }
    vp(n) {
        const res = [];
        for (let i = 0; i < n; i++) {
            res.push(this.i());
        }
        return res;
    }
}

function main() {
    const inputData = fs.readFileSync(0, 'utf8');
    const input = new WordReader(inputData);

    const n = input.i();
    const d = input.i();
    const arr = input.vp(n);
    const sumArr = arr.reduce((a, b) => a + b, 0);
    const sum = d - sumArr;

    let result;
    if (sum >= 10 * (n - 1)) {
        result = Math.floor(sum / 5);
    } else {
        result = -1;
    }
    console.log(result);
}

